// GENERATED by scripts/sync-functions.mjs from src/shared. Do not edit; run `npm run functions:sync`.
// Money as integers in minor units. No floating point anywhere in here:
// parsing and splitting are done on digit strings.

import { minorDigits } from './currencies.ts';
import { toLatinDigits } from './digits.ts';

export interface MoneyDisplayOptions {
  /** Show IRR amounts as toman (rial / 10). */
  irrAsToman?: boolean;
}

/** True when an IRR amount should be shown and typed in toman. */
export function usesToman(currency: string, opts: MoneyDisplayOptions = {}): boolean {
  return currency === 'IRR' && !!opts.irrAsToman;
}

/**
 * Digits after the decimal point in the unit the user sees and types.
 * For IRR shown as toman this is 1, because 1 toman = 10 rial (the stored unit).
 */
export function displayDigits(currency: string, opts: MoneyDisplayOptions = {}): number {
  return usesToman(currency, opts) ? 1 : minorDigits(currency);
}

/**
 * Parse what a person typed ("1,250.50", "۱۲٬۵۰۰", "1.250,5", "500 000") into
 * stored minor units. Returns null when the text is not a valid amount.
 */
export function parseAmount(
  input: string,
  currency: string,
  opts: MoneyDisplayOptions = {},
): number | null {
  const digits = displayDigits(currency, opts);
  const text = toLatinDigits(input).replace(/[\s  '’_]/g, '');
  if (!/^[0-9.,]+$/.test(text) || !/[0-9]/.test(text)) return null;

  let integer = text;
  let fraction = '';
  const lastDot = text.lastIndexOf('.');
  const lastComma = text.lastIndexOf(',');
  const sepIndex = Math.max(lastDot, lastComma);

  if (sepIndex >= 0) {
    const sep = text[sepIndex];
    const other = sep === '.' ? ',' : '.';
    const sepCount = text.split(sep).length - 1;
    const after = text.length - sepIndex - 1;
    // The last separator is a decimal point when another kind of separator is
    // also used (1,250.50 / 1.250,50), or when it appears once and has no
    // more digits after it than the currency allows (12.5 / 12,50).
    const isDecimal =
      digits > 0 &&
      sepCount === 1 &&
      after > 0 &&
      (text.includes(other) || after <= digits);
    if (isDecimal) {
      integer = text.slice(0, sepIndex);
      fraction = text.slice(sepIndex + 1);
    }
  }

  integer = integer.replace(/[.,]/g, '');
  if (!/^[0-9]*$/.test(integer) || !/^[0-9]*$/.test(fraction)) return null;
  if (fraction.length > digits) return null;

  // With toman, displayDigits is 1, so tenths of a toman are exactly rials and
  // `units` is already in the stored minor unit.
  const units = (integer || '0') + fraction.padEnd(digits, '0');
  const minor = Number(units.replace(/^0+(?=\d)/, ''));
  return Number.isSafeInteger(minor) ? minor : null;
}

export interface SplitAmount {
  negative: boolean;
  /** Integer part as Latin digits, no grouping. */
  integer: string;
  /** Fraction digits, trailing zeros trimmed ('' when whole). */
  fraction: string;
}

/** Split stored minor units into integer and fraction digit strings for display. */
export function splitMinor(minor: number, currency: string, opts: MoneyDisplayOptions = {}): SplitAmount {
  if (!Number.isSafeInteger(minor)) throw new RangeError(`Amount must be an integer: ${minor}`);
  const digits = displayDigits(currency, opts);
  const negative = minor < 0;
  const abs = String(Math.abs(minor)).padStart(digits + 1, '0');
  const integer = digits === 0 ? abs : abs.slice(0, -digits);
  const fraction = digits === 0 ? '' : abs.slice(-digits).replace(/0+$/, '');
  return { negative, integer, fraction };
}

/** Plain machine-readable decimal string (for CSV export, inputs): "1250.5". */
export function minorToDecimalString(minor: number, currency: string, opts: MoneyDisplayOptions = {}): string {
  const { negative, integer, fraction } = splitMinor(minor, currency, opts);
  return `${negative ? '-' : ''}${integer}${fraction ? `.${fraction}` : ''}`;
}
